pub(super) struct InferF<'a> {
    f: &'a Function,
    /// The binder of `f`.
    fid: usize,
    params: Vec<SParam>,
    ids: Vec<usize>,
    /// The position in `ids` of each parameter's binder, the first where two are one; empty
    /// when no parameter has a default, the only reader being [`Ck::note_default_reads`].
    index: HashMap<usize, usize>,
    given: Vec<Option<Ty>>,
    level: usize,
    tys: Vec<Ty>,
    /// The parameter whose default is checked next.
    i: usize,
    /// While a default is checked: the class of its parameter's type, if it is one.
    waiting: Option<Option<usize>>,
    /// While a closed default is checked for `given`: the number of errors before it.
    closed: Option<usize>,
}

/// The position in `ids` of each id, the first where it occurs more than once: for each `b`,
/// `first_positions(ids).get(&b)` is `ids.iter().position(|&id| id == b)`, the search it
/// replaced (commit e658dbd45), whether or not the ids are distinct. O(p) for p ids.
fn first_positions(ids: &[usize]) -> HashMap<usize, usize> {
    let mut index = HashMap::with_capacity(ids.len());
    for (j, &id) in ids.iter().enumerate() {
        index.entry(id).or_insert(j);
    }
    index
}

pub(super) struct AtomF<'a> {
    name: &'a str,
    positional: &'a [Expr],
    named: &'a [(String, Expr)],
    started: usize,
    items: Vec<Ty>,
    fields: BTreeMap<Arc<str>, Ty>,
    /// The span of the whole atom with its payload.
    span: Span,
}

/// Whether the type of `e` is printed as `e` is written, so that a message shows the code
/// alone: a literal ([`is_literal`]), a string or an atom with no hole, or a tuple of such.
fn written_as_its_type(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Str(parts) => parts.iter().all(|p| matches!(p, StrPart::Text(_))),
        ExprKind::Atom(_) => true,
        ExprKind::Tuple(es) => es.iter().all(written_as_its_type),
        _ => is_literal(e),
    }
}

